const data = $input.first().json;
const state = $getWorkflowStaticData('global');
if (data.error || !Array.isArray(data.reports)) {
  if (Date.now() - (state.lastMonitorAlert || 0) < 3600000) return [];
  return [{json:{monitorError:true,reports:[],subject:'OpenBrain ingest alert monitor cannot read reports',text:'The ingestion alert monitor could not read or claim failure reports. Ingest failures may be unreported. Check the OpenBrain database and this workflow. No raw database error or credential is included in this email.'}}];
}
if (!data.reports.length) return [];
const reports = data.reports;
const synthetic = reports.every(r=>r.synthetic==='true');
return [{json:{monitorError:false,reports,subject:(synthetic?'[TEST] ':'')+'OpenBrain: '+reports.length+' unnotified ingestion failure(s)',text:'OpenBrain has ingestion failures requiring review. This digest includes previously unnotified history; timestamps below distinguish old failures from new ones.\n\n'+reports.map(r=>r.created_at+' | report '+r.id+(r.synthetic==='true'?' | synthetic verification':'')).join('\n')+'\n\nReview openbrain.public.reports by report ID and the consume failed/ directory. No document contents, file names, tracebacks, or secrets are included in this email.'}}];

const smtp = $input.first().json;
const prepared = $('Prepare digest').first().json;
const accepted = (smtp.accepted || []).map(v=>String(v).toLowerCase());
if (!accepted.includes("alerts@example.com") || !smtp.messageId) throw new Error('SMTP did not confirm acceptance; reports remain pending');
const state = $getWorkflowStaticData('global');
if (prepared.monitorError) { state.lastMonitorAlert=Date.now(); return []; }
state.lastMonitorAlert=0;
return [{json:{reports:prepared.reports,messageId:smtp.messageId}}];

const expected = $('Verify SMTP acceptance').first().json.reports.length;
if ($input.first().json.acknowledged !== expected) throw new Error('Delivery acknowledgement count mismatch; inspect leases before retrying');
return [{json:{acknowledged:expected}}];
